# -*- coding: utf-8 -*-
<!-- AI-Assisted: Initial draft generated by Claude Code; reviewed and modified by author. -->
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>四人版飞行棋游戏</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            width: 100vw;
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            font-family: Arial, sans-serif;
        }

        .game-container {
            position: relative;
            width: 100%;
            height: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .game-board {
            position: relative;
            width: 90%;
            height: 90%;
            max-width: 1000px;
            max-height: 1000px;
            background: white;
            border-radius: 20px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
            display: flex;
            justify-content: space-between;
            align-items: stretch;
            padding: 30px;
        }

        .player-zone {
            width: 150px;
            height: 150px;
            border-radius: 10px;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 20px;
            color: white;
            font-weight: bold;
            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5);
            position: absolute;
        }

        .player-zone-red {
            background: linear-gradient(135deg, #ff6b6b, #ff5252);
            top: 30px;
            left: 30px;
        }

        .player-zone-yellow {
            background: linear-gradient(135deg, #ffd93d, #ffca00);
            top: 30px;
            right: 30px;
        }

        .player-zone-blue {
            background: linear-gradient(135deg, #6bceff, #4fb3ff);
            bottom: 30px;
            right: 30px;
        }

        .player-zone-green {
            background: linear-gradient(135deg, #51cf66, #37b24d);
            bottom: 30px;
            left: 30px;
        }

        .center-panel {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            gap: 30px;
            background: rgba(255, 255, 255, 0.95);
            padding: 50px;
            border-radius: 15px;
            box-shadow: 0 5px 20px rgba(0, 0, 0, 0.1);
            z-index: 10;
        }

        .dice-button {
            width: 120px;
            height: 120px;
            border-radius: 60px;
            background: linear-gradient(135deg, #667eea, #764ba2);
            border: none;
            color: white;
            font-size: 24px;
            font-weight: bold;
            cursor: pointer;
            box-shadow: 0 5px 15px rgba(102, 126, 234, 0.4);
            transition: all 0.3s ease;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .dice-button:hover {
            transform: scale(1.05);
            box-shadow: 0 8px 20px rgba(102, 126, 234, 0.6);
        }

        .dice-button:active {
            transform: scale(0.95);
        }

        .dice-display {
            width: 100px;
            height: 100px;
            border-radius: 10px;
            background: white;
            border: 3px solid #667eea;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 48px;
            font-weight: bold;
            color: #667eea;
            box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.1);
        }

        .label {
            font-size: 14px;
            color: #666;
            text-align: center;
            margin-top: 10px;
        }
    </style>
</head>
<body>
    <div class="game-container">
        <div class="game-board">
            <div class="player-zone player-zone-red">红队准备区</div>
            <div class="player-zone player-zone-yellow">黄队准备区</div>
            <div class="player-zone player-zone-blue">蓝队准备区</div>
            <div class="player-zone player-zone-green">绿队准备区</div>

            <div class="center-panel">
                <div>
                    <button class="dice-button" id="diceBtn">掷骰子</button>
                    <div class="label">点击掷骰子</div>
                </div>
                <div>
                    <div class="dice-display" id="diceDisplay">-</div>
                    <div class="label">当前骰子点数</div>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.getElementById('diceBtn').addEventListener('click', function() {
            const diceNum = Math.floor(Math.random() * 6) + 1;
            const diceDisplay = document.getElementById('diceDisplay');
            diceDisplay.textContent = diceNum;
            diceDisplay.style.animation = 'none';
            setTimeout(() => {
                diceDisplay.style.animation = 'roll 0.6s ease-out';
            }, 10);
        });
    </script>

    <style>
        @keyframes roll {
            0% {
                transform: rotateZ(0deg) scale(0.8);
                opacity: 0.5;
            }
            50% {
                transform: rotateZ(180deg) scale(1.1);
            }
            100% {
                transform: rotateZ(360deg) scale(1);
                opacity: 1;
            }
        }
    </style>
</body>
</html>
